  function vtGoi(r,yc){
    var L=['VIỆC TIẾP THEO, làm nối tiếp việc đã xong.','Việc trước: "'+String(r.title||'').slice(0,160)+'" ('+fmtDay(r.date)+' '+(r.time||'')+').'];
    if(r.folder)L.push('Kết quả việc trước nằm trong bộ não, thư mục: '+r.folder+' . Đọc các file ở đó trước khi làm.');
    var sum=String(r.summary||'').replace(/\s+/g,' ').trim().slice(0,900);if(sum)L.push('Tóm tắt kết quả việc trước: '+sum);
    var ph=(r.plan||[]).filter(function(p){return p.out;}).slice(0,6).map(function(p){return '- '+agentName(p.agent)+': '+String(p.viec||'').slice(0,80)+' => '+String(p.out).replace(/\s+/g,' ').slice(0,260);});
    if(ph.length)L.push('Các phần đã làm:\n'+ph.join('\n'));
    L.push('YÊU CẦU MỚI CỦA '+String(OWNER_REF||'anh').toUpperCase()+': '+yc);
    L.push('Cách làm: dùng kết quả việc trước làm đầu vào, KHÔNG làm lại từ đầu, nói rõ đã lấy gì từ kết quả cũ. Thiếu thông tin quan trọng thì hỏi lại ngắn gọn.');
    return L.join('\n').slice(0,4900);}
  document.addEventListener('click',function(e){
    var c=e.target.closest&&e.target.closest('[data-vt-chip]');
    if(c){var ta=document.getElementById('vt-ta');if(ta){ta.value=c.getAttribute('data-vt-txt')||c.textContent;ta.focus();}return;}
    var g=e.target.closest&&e.target.closest('[data-vt-giao]');if(!g)return;
    var box=g.closest('#vt-box'),r=box&&findResult(box.getAttribute('data-vt')),t=document.getElementById('vt-ta'),tt=document.getElementById('vt-tt');
    if(!r)return;var yc=String((t&&t.value)||'').trim();
    if(yc.length<6){if(tt)tt.textContent='Anh nói hoặc gõ việc kế tiếp trước nhé.';if(t)t.focus();return;}
    var text=vtGoi(r,yc);
    try{Drawer.close();}catch(x){}
    go('ban-lam-viec');var ta2=$('#demo-input');ta2.value=text;ta2.dispatchEvent(new Event('input'));
    setTimeout(function(){var rb=$('#demo-run');if(rb)rb.click();},350);
    try{toast('Đã giao việc tiếp. Đội nhận kết quả việc trước làm đầu vào.');}catch(x){}
  });
  /* Phần kiểm duyệt do anh xem lại (state "owner"): có nút Đã xem xong để ghi nhận, không để phần đó treo "Chờ anh làm" mãi. */
  async function ownerXong(r,n){
    if(!writable()||r.local){toast('Chưa ghi được: anh đang ở quyền xem hoặc kết quả chưa lưu.');return false;}
    var now=new Date().toISOString(),pp=(r.plan||[]).filter(function(p){return p.n===n;})[0];
    var plan=(r.plan||[]).map(function(p){return (p.n===n&&p.state==='owner')?Object.assign({},p,{state:'done',approved:true,approvedAt:now}):p;});
    var upd={plan:plan,updated:now};
    try{await S.db.collection('results').doc(r.id).update(upd);}catch(e){handleWriteError(e);return false;}
    r.plan=plan;r.updated=now;
    if(pp&&pp.taskId)S.tasks.filter(function(t){return t.id===pp.taskId&&norm(t.status)!=='xong';}).forEach(function(t){S.db.collection('tasks').doc(t.id).update({status:'xong',output:'Anh đã xem xong',updated:now}).catch(function(){});});
    try{toast('Đã ghi: anh xem xong phần này.');}catch(x){}
    return true;}
  document.addEventListener('click',async function(e){
    var b=e.target.closest&&e.target.closest('[data-owner-xong]');if(!b)return;e.preventDefault();e.stopPropagation();
    var v=String(b.getAttribute('data-owner-xong')).split('|'),r=findResult(v[0]);if(!r)return;b.disabled=true;
    var ok=await ownerXong(r,Number(v[1]));if(ok){try{openResult(r.id,v[1]);}catch(x){}}else b.disabled=false;
  },true);
  /* Nút "Làm tiếp từ kết quả này" ở chân cửa sổ: cuộn tới khu Việc tiếp theo (có ở mọi tab) và đặt con trỏ vào ô nhập. */
  document.addEventListener('click',function(e){
    var b=e.target.closest&&e.target.closest('[data-vt-mo]');if(!b)return;e.preventDefault();
    var box=document.getElementById('vt-box');if(!box)return;
    box.scrollIntoView({behavior:'smooth',block:'center'});
    var ta=document.getElementById('vt-ta');if(ta)setTimeout(function(){ta.focus();},250);
    box.classList.add('vt-nhay');setTimeout(function(){box.classList.remove('vt-nhay');},1400);
  });
